import { readFileSync } from 'node:fs'

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const mkErr = (e) => ({ err: e })
const mkText = (s) => ({ text: s })
const isErr = (v) => typeof v === 'object' && v !== null && 'err' in v
const isText = (v) => typeof v === 'object' && v !== null && 'text' in v

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) fail('error: usage: cli.js values|deps')
const mode = args[0]

// ---------- addresses ----------
function parseAddr(s) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(s)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const L = m[1].toUpperCase()
  let col
  if (L.length === 1) col = L.charCodeAt(0) - 64
  else col = 26 + (L.charCodeAt(0) - 65) * 26 + (L.charCodeAt(1) - 64)
  return { col, row }
}
function colName(c) {
  if (c <= 26) return String.fromCharCode(64 + c)
  const k = c - 27
  return String.fromCharCode(65 + Math.floor(k / 26)) + String.fromCharCode(65 + (k % 26))
}
const addrStr = (col, row) => colName(col) + row
const key = (col, row) => col * 1000 + row

// ---------- sheet parse ----------
const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const cells = new Map() // key -> {col,row,content}
lines.forEach((raw, i) => {
  const line = raw.replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') return
  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(line)
  const word = m[1]
  const a = parseAddr(word)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${word}`)
  const k = key(a.col, a.row)
  if (cells.has(k)) fail(`error: line ${i + 1}: cell ${word} is declared twice`)
  cells.set(k, { col: a.col, row: a.row, content: m[2] })
})
const sorted = [...cells.values()].sort((x, y) => x.col - y.col || x.row - y.row)

// ---------- formula parser ----------
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ t: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=)/.exec(s.slice(i)))) { toks.push({ t: 'op', v: m[0] }); i += 2; continue }
    if ('^*/+-=<>():,'.includes(c)) { toks.push({ t: 'op', v: c }); i++; continue }
    return null
  }
  return toks
}

function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  let stray = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
  const bad = () => { throw new Error('syntax') }
  function cmp() {
    let l = add()
    while (peek() && peek().t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().v)) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { type: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { type: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { type: 'un', op, x: unary() } }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) bad()
    if (t.t === 'num') { p++; return { type: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) bad()
      p++
      return { type: 'paren', x: e }
    }
    if (t.t === 'word') {
      p++
      const up = t.v.toUpperCase()
      if (isOp('(')) {
        p++
        const as = []
        if (isOp(')')) { p++ } else {
          for (;;) {
            const e = cmp()
            if (e.type === 'range') stray--
            as.push(e)
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            bad()
          }
        }
        return { type: 'call', name: up, args: as }
      }
      if (isOp(':')) {
        p++
        const t2 = toks[p]
        if (!t2 || t2.t !== 'word') bad()
        p++
        stray++
        return { type: 'range', a: parseAddr(t.v), b: parseAddr(t2.v) }
      }
      if (up === 'TRUE') return { type: 'bool', v: true }
      if (up === 'FALSE') return { type: 'bool', v: false }
      return { type: 'ref', a: parseAddr(t.v) }
    }
    bad()
  }
  try {
    const e = cmp()
    if (p < toks.length) bad()
    return { ast: e, misplaced: stray > 0 }
  } catch (e) {
    if (e.message === 'syntax') return null
    throw e
  }
}

function rangeCells(n) {
  if (!n.a || !n.b) return null
  const c1 = Math.min(n.a.col, n.b.col), c2 = Math.max(n.a.col, n.b.col)
  const r1 = Math.min(n.a.row, n.b.row), r2 = Math.max(n.a.row, n.b.row)
  return { c1, c2, r1, r2 }
}

function collectDeps(n, set) {
  switch (n.type) {
    case 'ref': if (n.a) set.add(key(n.a.col, n.a.row)); break
    case 'range': {
      const r = rangeCells(n)
      if (r) for (let c = r.c1; c <= r.c2; c++) for (let w = r.r1; w <= r.r2; w++) set.add(key(c, w))
      break
    }
    case 'call': n.args.forEach((a) => collectDeps(a, set)); break
    case 'un': case 'paren': collectDeps(n.x, set); break
    case 'bin': collectDeps(n.l, set); collectDeps(n.r, set); break
  }
}

// ---------- evaluation ----------
const parsed = new Map()
function getParsed(cell) {
  if (!parsed.has(cell)) {
    parsed.set(cell, cell.content[0] === '=' ? parseFormula(cell.content.slice(1)) : undefined)
  }
  return parsed.get(cell)
}

const memo = new Map()
const active = new Set()

function cellValue(col, row) {
  const k = key(col, row)
  if (memo.has(k)) return memo.get(k)
  const cell = cells.get(k)
  if (!cell) return 0
  if (active.has(k)) return mkErr('#CYCLE!')
  active.add(k)
  let v
  if (cell.content[0] === '=') {
    const f = getParsed(cell)
    if (!f || f.misplaced) v = mkErr('#ERR!')
    else v = evalNode(f.ast)
  } else v = literal(cell.content)
  active.delete(k)
  memo.set(k, v)
  return v
}

function literal(s) {
  if (s === '') return 0
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return Number(s)
  if (ERRS.includes(s)) return mkErr(s)
  return mkText(s)
}

const fin = (x) => (Number.isFinite(x) ? x : mkErr('#DIV/0!'))
function toNum(v) {
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
  return mkErr('#VALUE!')
}
const rank = (v) => (typeof v === 'number' ? 0 : isText(v) ? 1 : 2)
function cmpCP(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compare(a, b) {
  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra - rb
  if (ra === 0) return a < b ? -1 : a > b ? 1 : 0
  if (ra === 1) return cmpCP(a.text, b.text)
  return (a ? 1 : 0) - (b ? 1 : 0)
}

function argValues(args) {
  const out = []
  for (const a of args) {
    if (a.type === 'range') {
      const r = rangeCells(a)
      if (!r) out.push(mkErr('#REF!'))
      else for (let c = r.c1; c <= r.c2; c++) for (let w = r.r1; w <= r.r2; w++) out.push(cellValue(c, w))
    } else out.push(evalNode(a))
  }
  return out
}

function evalNode(n) {
  switch (n.type) {
    case 'num': return n.v
    case 'bool': return n.v
    case 'paren': return evalNode(n.x)
    case 'ref': return n.a ? cellValue(n.a.col, n.a.row) : mkErr('#REF!')
    case 'range': return mkErr('#ERR!')
    case 'un': {
      const v = evalNode(n.x)
      if (isErr(v)) return v
      const x = toNum(v)
      if (isErr(x)) return x
      return n.op === '-' ? fin(-x) : x
    }
    case 'bin': {
      const l = evalNode(n.l)
      if (isErr(l)) return l
      const r = evalNode(n.r)
      if (isErr(r)) return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const c = compare(l, r)
        switch (n.op) {
          case '=': return c === 0
          case '<>': return c !== 0
          case '<': return c < 0
          case '<=': return c <= 0
          case '>': return c > 0
          default: return c >= 0
        }
      }
      const a = toNum(l)
      if (isErr(a)) return a
      const b = toNum(r)
      if (isErr(b)) return b
      switch (n.op) {
        case '+': return fin(a + b)
        case '-': return fin(a - b)
        case '*': return fin(a * b)
        case '/': return b === 0 ? mkErr('#DIV/0!') : fin(a / b)
        default: return fin(Math.pow(a, b))
      }
    }
    case 'call': return evalCall(n)
  }
}

function evalCall(n) {
  const { name, args } = n
  const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
  if (!known.includes(name)) return mkErr('#NAME?')
  if (name === 'IF') {
    if (args.length !== 3) return mkErr('#ERR!')
    if (args.some((a) => a.type === 'range')) return mkErr('#ERR!')
    const c = evalNode(args[0])
    if (isErr(c)) return c
    let t
    if (typeof c === 'boolean') t = c
    else if (typeof c === 'number') t = c !== 0
    else return mkErr('#VALUE!')
    return evalNode(args[t ? 1 : 2])
  }
  if (name === 'ABS') {
    if (args.length !== 1 || args[0].type === 'range') return mkErr('#ERR!')
    const v = evalNode(args[0])
    if (isErr(v)) return v
    const x = toNum(v)
    return isErr(x) ? x : Math.abs(x)
  }
  if (args.length < 1) return mkErr('#ERR!')
  const vals = argValues(args)
  const e = vals.find(isErr)
  if (e) return e
  if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (isErr(x)) return x
    nums.push(x)
  }
  switch (name) {
    case 'SUM': return fin(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return nums.reduce((a, b) => (b < a ? b : a))
    case 'MAX': return nums.reduce((a, b) => (b > a ? b : a))
    default: return fin(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
}

function show(v) {
  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  if (isErr(v)) return v.err
  return v.text
}

const out = []
for (const cell of sorted) {
  const name = addrStr(cell.col, cell.row)
  if (mode === 'values') {
    out.push(`${name}=${show(cellValue(cell.col, cell.row))}`)
  } else {
    let line = name + ':'
    const f = cell.content[0] === '=' ? getParsed(cell) : null
    if (f) {
      const set = new Set()
      collectDeps(f.ast, set)
      const ks = [...set].sort((a, b) => a - b)
      for (const k of ks) line += ' ' + addrStr(Math.floor(k / 1000), k % 1000)
    }
    out.push(line)
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
