    case 'ref': if (n.a) set.add(key(n.a.col, n.a.row)); break
    case 'range': {
      const r = rangeCells(n)
      if (r) for (let c = r.c1; c <= r.c2; c++) for (let w = r.r1; w <= r.r2; w++) set.add(key(c, w))
      break
    }
    case 'call': n.args.forEach((a) => collectDeps(a, set)); break
    case 'un': case 'paren': collectDeps(n.x, set); break
    case 'bin': collectDeps(n.l, set); collectDeps(n.r, set); break
  }
}

// ---------- evaluation ----------
const parsed = new Map()
function getParsed(cell) {
  if (!parsed.has(cell)) {
    parsed.set(cell, cell.content[0] === '=' ? parseFormula(cell.content.slice(1)) : undefined)
  }
  return parsed.get(cell)
}

const memo = new Map()
const active = new Set()

function cellValue(col, row) {
  const k = key(col, row)
  if (memo.has(k)) return memo.get(k)
  const cell = cells.get(k)
  if (!cell) return 0
  if (active.has(k)) return mkErr('#CYCLE!')
  active.add(k)
  let v
  if (cell.content[0] === '=') {
    const f = getParsed(cell)
    if (!f || f.misplaced) v = mkErr('#ERR!')
    else v = evalNode(f.ast)
  } else v = literal(cell.content)
  active.delete(k)
  memo.set(k, v)
  return v
}

function literal(s) {
  if (s === '') return 0
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return Number(s)
  if (ERRS.includes(s)) return mkErr(s)
  return mkText(s)
}

const fin = (x) => (Number.isFinite(x) ? x : mkErr('#DIV/0!'))
function toNum(v) {
  if (typeof v === 'number') return v
  if (typeof v === 'boolean') return v ? 1 : 0
