  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra - rb
  if (ra === 0) return a < b ? -1 : a > b ? 1 : 0
  if (ra === 1) return cmpCP(a.text, b.text)
  return (a ? 1 : 0) - (b ? 1 : 0)
}

function argValues(args) {
  const out = []
  for (const a of args) {
    if (a.type === 'range') {
      const r = rangeCells(a)
      if (!r) out.push(mkErr('#REF!'))
      else for (let c = r.c1; c <= r.c2; c++) for (let w = r.r1; w <= r.r2; w++) out.push(cellValue(c, w))
