}

function evalNode(n) {
  switch (n.type) {
    case 'num': return n.v
    case 'bool': return n.v
    case 'paren': return evalNode(n.x)
    case 'ref': return n.a ? cellValue(n.a.col, n.a.row) : mkErr('#REF!')
    case 'range': return mkErr('#ERR!')
    case 'un': {
      const v = evalNode(n.x)
      if (isErr(v)) return v
      const x = toNum(v)
      if (isErr(x)) return x
      return n.op === '-' ? fin(-x) : x
    }
    case 'bin': {
      const l = evalNode(n.l)
      if (isErr(l)) return l
      const r = evalNode(n.r)
      if (isErr(r)) return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const c = compare(l, r)
        switch (n.op) {
          case '=': return c === 0
          case '<>': return c !== 0
          case '<': return c < 0
          case '<=': return c <= 0
          case '>': return c > 0
          default: return c >= 0
        }
      }
      const a = toNum(l)
      if (isErr(a)) return a
      const b = toNum(r)
      if (isErr(b)) return b
      switch (n.op) {
        case '+': return fin(a + b)
        case '-': return fin(a - b)
        case '*': return fin(a * b)
        case '/': return b === 0 ? mkErr('#DIV/0!') : fin(a / b)
        default: return fin(Math.pow(a, b))
      }
    }
    case 'call': return evalCall(n)
  }
}

function evalCall(n) {
  const { name, args } = n
  const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
  if (!known.includes(name)) return mkErr('#NAME?')
  if (name === 'IF') {
    if (args.length !== 3) return mkErr('#ERR!')
    if (args.some((a) => a.type === 'range')) return mkErr('#ERR!')
    const c = evalNode(args[0])
    if (isErr(c)) return c
    let t
    if (typeof c === 'boolean') t = c
    else if (typeof c === 'number') t = c !== 0
    else return mkErr('#VALUE!')
    return evalNode(args[t ? 1 : 2])
  }
  if (name === 'ABS') {
    if (args.length !== 1 || args[0].type === 'range') return mkErr('#ERR!')
    const v = evalNode(args[0])
    if (isErr(v)) return v
    const x = toNum(v)
    return isErr(x) ? x : Math.abs(x)
  }
  if (args.length < 1) return mkErr('#ERR!')
  const vals = argValues(args)
  const e = vals.find(isErr)
  if (e) return e
  if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (isErr(x)) return x
    nums.push(x)
  }
  switch (name) {
    case 'SUM': return fin(nums.reduce((a, b) => a + b, 0))
    case 'MIN': return nums.reduce((a, b) => (b < a ? b : a))
    case 'MAX': return nums.reduce((a, b) => (b > a ? b : a))
    default: return fin(nums.reduce((a, b) => a + b, 0) / nums.length)
  }
}

function show(v) {
  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  if (isErr(v)) return v.err
  return v.text
}

const out = []
for (const cell of sorted) {
  const name = addrStr(cell.col, cell.row)
  if (mode === 'values') {
    out.push(`${name}=${show(cellValue(cell.col, cell.row))}`)
  } else {
    let line = name + ':'
    const f = cell.content[0] === '=' ? getParsed(cell) : null
    if (f) {
      const set = new Set()
      collectDeps(f.ast, set)
      const ks = [...set].sort((a, b) => a - b)
      for (const k of ks) line += ' ' + addrStr(Math.floor(k / 1000), k % 1000)
    }
    out.push(line)
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')
