    if (w.length !== 4 - 0 && w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], Number(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) used.push(x)
    if (!deps.has(w[1])) deps.set(w[1], new Set())
    for (const d of w.slice(2)) deps.get(w[1]).add(d)
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
})
for (const x of used) if (!cost.has(x)) fail(`error: unknown task ${x}`)

const names = [...cost.keys()].sort()
const dl = new Map(names.map(k => [k, [...(deps.get(k) || [])].sort()]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = k => {
    state.set(k, 1)
    stack.push(k)
    for (const d of dl.get(k)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d)).concat(d)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!s) visit(d)
    }
    stack.pop()
    state.set(k, 2)
  }
  for (const k of names) if (!state.get(k)) visit(k)
}

const start = new Map(), finish = new Map(), depth = new Map()
const calc = k => {
  if (finish.has(k)) return
  let s = 0, d = 0
  for (const x of dl.get(k)) {
    calc(x)
    s = Math.max(s, finish.get(x))
    d = Math.max(d, depth.get(x) + 1)
  }
  start.set(k, s); finish.set(k, s + cost.get(k)); depth.set(k, d)
}
names.forEach(calc)
const total = names.reduce((m, k) => Math.max(m, finish.get(k)), 0)

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const k of names) (ws[depth.get(k)] ||= []).push(k)
  ws.forEach((g, i) => { out += `wave ${i}: ${g.join(' ')}\n` })
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const k of names) out += `${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}\n`
  out += `total ${total}\n`
} else {
  const rev = new Map(names.map(k => [k, []]))
  for (const k of names) for (const d of dl.get(k)) rev.get(d).push(k)
  const prio = new Map()
  const pr = k => {
    if (prio.has(k)) return prio.get(k)
    let m = 0
    for (const x of rev.get(k)) m = Math.max(m, pr(x))
    prio.set(k, m + cost.get(k))
    return prio.get(k)
  }
  names.forEach(pr)
  const free = new Array(workers).fill(0)
  const ran = Array.from({ length: workers }, () => [])
  const done = new Map()
  const pending = new Set(names)
  let t = 0, makespan = 0
  while (pending.size) {
    for (;;) {
      const w = free.findIndex(f => f <= t)
      if (w < 0) break
      let best = null
      for (const k of pending) {
        if (!dl.get(k).every(d => done.has(d) && done.get(d) <= t)) continue
        if (best === null || prio.get(k) > prio.get(best) || (prio.get(k) === prio.get(best) && k < best)) best = k
      }
      if (best === null) break
      pending.delete(best)
      const f = t + cost.get(best)
      done.set(best, f)
      free[w] = f
      ran[w].push(`${best}@${t}-${f}`)
      makespan = Math.max(makespan, f)
    }
    if (!pending.size) break
    const next = free.filter(f => f > t)
    if (!next.length) break
    t = Math.min(...next)
  }
  ran.forEach((r, i) => { out += `worker ${i}:${r.map(x => ' ' + x).join('')}\n` })
  out += `makespan ${makespan}\n`
}
process.stdout.write(out)
EOF
