export function parse(s) {
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/s.exec(s)
  return { scheme: m[1], authority: m[2], path: m[3], query: m[4], fragment: m[5] }
}

export function splitAuthority(a) {
  if (a === undefined) return undefined
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const rest = a.slice(at + 1)
  const colon = rest.indexOf(':', rest.lastIndexOf(']') + 1)
  if (colon < 0) return { userinfo, host: rest, port: undefined }
  return { userinfo, host: rest.slice(0, colon), port: rest.slice(colon + 1) }
}

const BAD = /%(?![0-9A-Fa-f]{2})/

export function checkPercent(t) {
  const a = splitAuthority(t.authority)
  const parts = [
    ['path', t.path], ['userinfo', a && a.userinfo], ['host', a && a.host],
    ['query', t.query], ['fragment', t.fragment],
  ]
  for (const [name, v] of parts) if (v !== undefined && BAD.test(v)) return name
  return null
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function pct(s) {
  if (s === undefined) return s
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}

const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

export function removeDots(input) {
  let out = ''
  while (input.length) {
    if (input.startsWith('../')) input = input.slice(3)
    else if (input.startsWith('./')) input = input.slice(2)
    else if (input.startsWith('/./')) input = input.slice(2)
    else if (input === '/.') input = '/'
    else if (input.startsWith('/../') || input === '/..') {
      input = input === '/..' ? '/' : input.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (input === '.' || input === '..') input = ''
    else {
      const i = input.indexOf('/', 1)
      const seg = i < 0 ? input : input.slice(0, i)
      out += seg
      input = input.slice(seg.length)
    }
  }
  return out
}

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function normalize(t) {
  const scheme = t.scheme === undefined ? undefined : lowerAscii(t.scheme)
  let authority
  if (t.authority !== undefined) {
    const a = splitAuthority(pct(t.authority))
    let port = a.port
    if (port === '' || (scheme in DEFAULT_PORT && port === DEFAULT_PORT[scheme])) port = undefined
    authority = (a.userinfo !== undefined ? a.userinfo + '@' : '') + lowerAscii(a.host) +
      (port !== undefined ? ':' + port : '')
  }
  let path = removeDots(pct(t.path))
  if (authority !== undefined && path === '') path = '/'
  return serialize({ scheme, authority, path, query: pct(t.query), fragment: pct(t.fragment) })
}

export function serialize(t) {
  return (t.scheme !== undefined ? t.scheme + ':' : '') +
    (t.authority !== undefined ? '//' + t.authority : '') + t.path +
    (t.query !== undefined ? '?' + t.query : '') +
    (t.fragment !== undefined ? '#' + t.fragment : '')
}

// Returns the unnormalized target plus the path to check for percent errors.
export function resolve(base, ref) {
  if (ref.scheme !== undefined) return { ...ref, path: ref.path, dotted: removeDots(ref.path) }
  if (ref.authority !== undefined) return { ...ref, scheme: base.scheme, dotted: removeDots(ref.path) }
  const t = { scheme: base.scheme, authority: base.authority, fragment: ref.fragment }
  if (ref.path === '') {
    t.path = base.path
    t.query = ref.query !== undefined ? ref.query : base.query
    t.dotted = t.path
    return t
  }
  t.query = ref.query
  if (ref.path.startsWith('/')) t.path = ref.path
  else if (base.authority !== undefined && base.path === '') t.path = '/' + ref.path
  else {
    const i = base.path.lastIndexOf('/')
    t.path = (i < 0 ? '' : base.path.slice(0, i + 1)) + ref.path
  }
  t.dotted = removeDots(t.path)
  return t
}
