    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      for (const x of w.slice(1)) used.push(x)
      if (!deps.has(w[1])) deps.set(w[1], new Set())
      for (const d of w.slice(2)) deps.get(w[1]).add(d)
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const x of used) if (!costs.has(x)) throw new Fail(`error: unknown task ${x}`)
  const names = [...costs.keys()].sort(cmp)
  const dmap = new Map(names.map((x) => [x, [...(deps.get(x) ?? [])].sort(cmp)]))
  return { names, costs, dmap }
}

function findCycle({ names, dmap }) {
  const state = new Map()
  const stack = []
  const visit = (x) => {
    state.set(x, 1)
    stack.push(x)
    for (const d of dmap.get(x)) {
      if (state.get(d) === 1) return [...stack.slice(stack.indexOf(d)), d]
      if (!state.has(d)) {
        const c = visit(d)
        if (c) return c
      }
    }
    stack.pop()
    state.set(x, 2)
    return null
  }
  for (const x of names) if (!state.has(x)) {
    const c = visit(x)
    if (c) return c
  }
  return null
}

function analyze(g) {
  const { names, costs, dmap } = g
  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  const calc = (x) => {
    if (finish.has(x)) return
    let s = 0
    let dp = 0
    for (const d of dmap.get(x)) {
      calc(d)
      s = Math.max(s, finish.get(d))
      dp = Math.max(dp, depth.get(d) + 1)
    }
    start.set(x, s)
    finish.set(x, s + costs.get(x))
    depth.set(x, dp)
  }
  names.forEach(calc)
  let total = 0
  for (const f of finish.values()) total = Math.max(total, f)
  return { start, finish, depth, total }
}

function pack(g, workers) {
  const { names, costs, dmap } = g
  const rev = new Map(names.map((x) => [x, []]))
  for (const x of names) for (const d of dmap.get(x)) rev.get(d).push(x)
  const prio = new Map()
