    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = null
      for (const x of names) {
        if (done.has(x)) continue
        if (!dmap.get(x).every((d) => fin.has(d) && fin.get(d) <= t)) continue
