      makespan = Math.max(makespan, f)
      runs[w].push(`${pick}@${t}-${f}`)
    }
    if (done.size >= names.length) break
    const next = freeAt.filter((f) => f > t)
    if (!next.length) break
    t = Math.min(...next)
  }
  return runs.map((r, i) => `worker ${i}:${r.map((s) => ' ' + s).join('')}\n`).join('') + `makespan ${makespan}\n`
}

function main(argv) {
  const [cmd, ...rest] = argv
  const usage = 'error: usage: cli.js waves|explain|pack <workers>'
  let workers = 0
  if ((cmd === 'waves' || cmd === 'explain') && rest.length === 0) {
    // ok
  } else if (cmd === 'pack' && rest.length === 1) {
    if (!/^[1-9][0-9]*$/.test(rest[0])) throw new Fail('error: workers must be a positive integer')
    workers = Number(rest[0])
  } else throw new Fail(usage)

  const g = parse(readFileSync(0, 'utf8'))
  const cyc = findCycle(g)
  if (cyc) throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
  if (cmd === 'pack') return pack(g, workers)
  const a = analyze(g)
  let out = ''
  if (cmd === 'waves') {
    const waves = []
    for (const x of g.names) (waves[a.depth.get(x)] ??= []).push(x)
    waves.forEach((ws, k) => {
      out += `wave ${k}: ${ws.join(' ')}\n`
    })
  } else {
    for (const x of g.names) {
      out += `${x} start=${a.start.get(x)} finish=${a.finish.get(x)} depth=${a.depth.get(x)}\n`
    }
  }
  return out + `total ${a.total}\n`
}

try {
  process.stdout.write(main(process.argv.slice(2)))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
"}

