  constructor(s) {
    this.s = s
    this.i = 0
  }
  ws() {
    while (isWs(this.s[this.i])) this.i++
  }
  // at end of line or at a comment start (after whitespace skipped)
  atEnd() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  name() {
    const c = this.s[this.i]
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    const st = this.i
    while (isBare(this.s[this.i])) this.i++
    if (this.i === st) fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const parts = []
    this.ws()
    parts.push(this.name())
    for (;;) {
