    if (ex.headerDefined) fail(`table ${dot(names)} is defined twice`)
    ex.headerDefined = true
    return ex
  }
  if (ex === undefined) {
    const n = newTable()
    cur.map.set(last, { t: 'array', items: [n], aot: true })
    return n
  }
  if (ex.t !== 'array' || !ex.aot) fail(`${dot(names)} is not an array of tables`)
  const n = newTable()
  ex.items.push(n)
  return n
}

