  if (lines[lines.length - 1] === '') lines.pop()
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    try {
      const d = t[0]
      if (['bucket', 'window', 'route', 'event'].includes(d) === false) throw new Fail(`unknown directive ${d}`)
      if (d !== 'event' && events.length > 0) throw new Fail('declarations must come before the first event')
      if (d === 'bucket' || d === 'window') {
        const n = d === 'bucket' ? 5 : 4
        if (t.length !== n) {
          throw new Fail(d === 'bucket' ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
        }
        if (!NAME.test(t[1])) throw new Fail(`invalid policy name ${t[1]}`)
        let p
        if (d === 'bucket') {
          const capacity = int('capacity', t[2], 1)
          const refill = int('refill', t[3], 0)
          const per = int('per', t[4], 1)
          p = { kind: 'bucket', capacity, refill, per }
        } else {
          p = { kind: 'window', limit: int('limit', t[2], 0), span: int('span', t[3], 1) }
        }
        if (policies.has(t[1])) throw new Fail(`policy ${t[1]} is declared twice`)
        p.name = t[1]
        policies.set(t[1], p)
      } else if (d === 'route') {
        if (t.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(t[1])) throw new Fail(`invalid route prefix ${t[1]}`)
        if (routes.has(t[1])) throw new Fail(`prefix ${t[1]} is routed twice`)
        const list = []
        for (const n of t.slice(2)) {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
          list.push(policies.get(n))
        }
        routes.set(t[1], list)
      } else {
        if (t.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = int('tick', t[1], 0)
        if (!NAME.test(t[2])) throw new Fail(`invalid key ${t[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${t[1]} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, key: t[2] })
      }
    } catch (e) {
      if (e instanceof Fail) throw new Fail(`line ${i + 1}: ${e.message}`)
      throw e
    }
  }
  return { routes, events }
}

function run({ routes, events }) {
  const states = new Map()
  const stat = (p, key) => {
    const id = p.name + '\0' + key
    let s = states.get(id)
    if (!s) {
      s = p.kind === 'bucket' ? { num: p.capacity * p.per, last: null } : { ticks: [], head: 0 }
      states.set(id, s)
    }
    return s
  }
  const out = []
  const per = new Map()
  for (const { tick, key } of events) {
    let best = null
    for (const pre of routes.keys()) if (key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    let denied = null
    if (best !== null) {
      const list = routes.get(best)
      const sts = list.map((p) => {
        const s = stat(p, key)
        if (p.kind === 'bucket') {
          if (s.last !== null) {
            const cap = p.capacity * p.per
            s.num += p.refill * (tick - s.last)
            if (s.num > cap) s.num = cap
          }
          s.last = tick
        } else {
          while (s.head < s.ticks.length && s.ticks[s.head] <= tick - p.span) s.head++
        }
        return s
      })
      for (let i = 0; i < list.length; i++) {
        const p = list[i], s = sts[i]
        const ok = p.kind === 'bucket' ? s.num >= p.per : BigInt(s.ticks.length - s.head) < p.limit
        if (!ok) { denied = p.name; break }
      }
      if (denied === null) {
        list.forEach((p, i) => {
          if (p.kind === 'bucket') sts[i].num -= p.per
          else sts[i].ticks.push(tick)
        })
      }
    }
    out.push(denied === null ? `${tick} ${key} allow` : `${tick} ${key} deny ${denied}`)
    const c = per.get(key) || { a: 0, d: 0 }
    if (denied === null) c.a++; else c.d++
    per.set(key, c)
  }
  if (mode === 'replay') return out.map((l) => l + '\n').join('')
  let a = 0, d = 0, s = ''
  for (const k of [...per.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
    const c = per.get(k)
    a += c.a; d += c.d
    s += `${k} allowed=${c.a} denied=${c.d}\n`
  }
  return s + `total allowed=${a} denied=${d}\n`
}

try {
  const text = readFileSync(0, 'utf8')
  process.stdout.write(run(parse(text)))
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exitCode = 2
}
EOF
