{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let candidates = null
const ballots = []
const NAME = /^[A-Za-z0-9_-]+$/

lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const t = line.split(/\s+/)
  const word = t[0]
  if (word === 'candidates') {
    if (candidates !== null || ballots.length > 0) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of t.slice(1)) {
      if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    candidates = t.slice(1)
  } else if (word === 'ballot') {
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const known = new Set(candidates || [])
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!known.has(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${word}`)
  }
})
if (candidates === null) fail('error: no candidates')

const total = ballots.reduce((s, b) => s + b.count, 0n)
const continuing = new Set(candidates)
const history = new Map(candidates.map(c => [c, []]))
const out = []
let round = 0
let result
for (;;) {
  round++
  const counts = new Map([...continuing].map(c => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find(p => continuing.has(p))
    if (c !== undefined) { counts.set(c, counts.get(c) + b.count); active += b.count }
  }
  for (const [c, v] of counts) history.get(c).push(v)
  const sorted = [...counts].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
  let line = `round ${round}: ` + sorted.map(([c, v]) => `${c}=${v}`).join(' ') + ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) { result = 'no winner'; break }
  const win = sorted.find(([, v]) => v * 2n > active)
  if (win) { result = `winner ${win[0]}`; break }
  let min = null
  for (const v of counts.values()) if (min === null || v < min) min = v
  let set = [...counts].filter(([, v]) => v === min).map(([c]) => c)
  let changed = true
  while (changed && set.length > 1) {
    changed = false
    for (let r = 0; r < round; r++) {
      const vals = set.map(c => history.get(c)[r])
      const m = vals.reduce((a, b) => (b < a ? b : a))
      if (vals.some(v => v !== m)) {
        set = set.filter(c => history.get(c)[r] === m)
        changed = true
        break
      }
    }
  }
  const elim = set.reduce((a, b) => (b > a ? b : a))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + result + '\n')
else process.stdout.write(`rounds ${round}\n${result}\n`)
EOF
