import { scan, ScanError } from './scanner.js'

const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'tokens' && args[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
const input = readFileSync(0).toString('utf8')
let tokens
try {
  tokens = scan(input)
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.reason}\n`)
  process.exit(2)
}
let out = ''
if (args[0] === 'tokens') {
  for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
} else {
  const counts = Object.fromEntries(KINDS.map((k) => [k, 0]))
  for (const t of tokens) counts[t.kind]++
  for (const k of KINDS) out += `${k} ${counts[k]}\n`
  out += `total ${tokens.length}\n`
}
process.stdout.write(out)
"}

{"file_path":"src/scanner.js","content":"export class ScanError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdChar = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

export function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  let i = 0
  let line = 1
  let col = 1
  const tokens = []

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else col++
    return c
  }
  const advN = (k) => {
    while (k-- > 0) adv()
  }

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      adv()
      continue
    }
    const sl = line
    const sc = col
    const start = i
    const push = (kind, body) => tokens.push({ line: sl, col: sc, kind, body })

    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      let depth = 0
      do {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') {
          depth++
          advN(2)
        } else if (cs[i] === '*' && cs[i + 1] === '/') {
          depth--
          advN(2)
        } else adv()
      } while (depth > 0)
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      advN(2)
      let val = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = adv()
        if (d === '"') break
        val += d
      }
      push('rawstring', JSON.stringify(val))
      continue
    }
    if (isIdStart(c)) {
      while (i < n && isIdChar(cs[i])) adv()
      const w = cs.slice(start, i).join('')
      push(KEYWORDS.has(w) ? 'keyword' : 'ident', w)
      continue
    }
    if (isDigit(c)) {
      // digit run with single underscores between digits
      const run = (ok) => {
        let any = false
        while (i < n) {
          if (ok(cs[i])) {
            adv()
            any = true
          } else if (cs[i] === '_' && any && ok(cs[i - 1]) && ok(cs[i + 1])) adv()
          else break
        }
        return any
      }
      let bad = false
      const p = cs[i + 1]
      const radix = c === '0' ? { x: isHex, X: isHex, b: (d) => d === '0' || d === '1', B: (d) => d === '0' || d === '1', o: (d) => d >= '0' && d <= '7' && d.length === 1, O: (d) => d >= '0' && d <= '7' && d.length === 1 }[p] : undefined
      if (radix) {
        advN(2)
        if (!run(radix)) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) {
          adv()
          run(isDigit)
        }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1])) {
            adv()
            run(isDigit)
          } else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) {
            advN(2)
            run(isDigit)
          }
        }
      }
      if (bad || isIdChar(cs[i])) {
        while (i < n && isIdChar(cs[i])) adv()
