const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < Math.min(x.length, y.length); i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (map) => [...map.keys()].sort(cmp)

function json(node, indent) {
  const pad = '  '.repeat(indent + 1)
  const end = '  '.repeat(indent)
  if (node.t === 'table') {
    const ks = sortedKeys(node.map)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + json(node.map.get(k), indent + 1)).join(',\n') + '\n' + end + '}'
  }
  if (node.t === 'array') {
    if (!node.items.length) return '[]'
    return '[\n' + node.items.map((n) => pad + json(n, indent + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(node.v)
}

export const renderJson = (root) => json(root, 0) + '\n'

export function renderKeys(root) {
  const out = []
  const walk = (node, path) => {
    if (node.t === 'table') {
      for (const k of sortedKeys(node.map)) visit(node.map.get(k), path === null ? k : path + '.' + k)
    } else if (node.t === 'array') {
      node.items.forEach((n, i) => visit(n, path + '[' + i + ']'))
    }
  }
  const visit = (node, path) => {
    out.push(path + ' ' + node.type)
    walk(node, path)
  }
  walk(root, null)
  return out.map((l) => l + '\n').join('')
}
