export class ParseError extends Error {}

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

function err(n, msg) {
  return new ParseError(`error: line ${n}: ${msg}`)
}

export function parseElection(text) {
  const lines = text.split('\n')
  let candidates = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const w = line.split(/\s+/)
    if (w[0] === 'candidates') {
      if (candidates !== null) throw err(n, 'candidates must be declared once, before any ballot')
      if (w.length < 2) throw err(n, 'expected candidates <name>...')
      const seen = new Set()
      for (const name of w.slice(1)) {
        if (!NAME.test(name)) throw err(n, `invalid candidate name ${name}`)
        if (seen.has(name)) throw err(n, `candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = w.slice(1)
    } else if (w[0] === 'ballot') {
      if (candidates === null) throw err(n, 'candidates must be declared once, before any ballot')
      if (w.length < 3) throw err(n, 'expected ballot <count> <candidate>...')
      if (!COUNT.test(w[1])) throw err(n, 'count must be a positive integer')
      const seen = new Set()
      for (const name of w.slice(2)) {
        if (!candidates.includes(name)) throw err(n, `unknown candidate ${name}`)
        if (seen.has(name)) throw err(n, `candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
    } else {
      throw err(n, `unknown directive ${w[0]}`)
    }
  }
  if (candidates === null) throw new ParseError('error: no candidates')
  return { candidates, ballots }
}
