const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    let total = 0n
    for (const b of ballots) {
      total += b.count
      const pick = b.prefs.find((p) => continuing.has(p))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    for (const [c, v] of votes) history.get(c).push(v)
    const counts = [...votes].sort((a, b) => cmp(b[1], a[1]) || cmp(a[0], b[0]))
    const round = { counts, exhausted: total - active, eliminated: null }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    const top = counts[0]
    if (top[1] * 2n > active) return { rounds, winner: top[0] }
    const min = counts[counts.length - 1][1]
    const tied = counts.filter(([, v]) => v === min).map(([c]) => c)
    tied.sort((a, b) => {
      const ha = history.get(a)
      const hb = history.get(b)
      for (let i = 0; i < ha.length; i++) if (ha[i] !== hb[i]) return cmp(ha[i], hb[i])
      return cmp(b, a)
    })
    round.eliminated = tied[0]
    continuing.delete(tied[0])
  }
}
